From 331139b2a609a860273643ab070cfffb6838b486 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:18:30 +0100
Subject: [PATCH] applets/systemtray: slide back to the item grid when going
 back

Going back from an applet to the grid of items swapped the views at once
with only the labels fading in, while opening an applet slides it in.
Now the grid slides in from the side like a StackView pop transition.

BUG: 459201
---
 .../systemtray/qml/ExpandedRepresentation.qml | 34 +++++++++++++++++++
 1 file changed, 34 insertions(+)

diff --git a/applets/systemtray/qml/ExpandedRepresentation.qml b/applets/systemtray/qml/ExpandedRepresentation.qml
index 7e29cb1a6e..85a76f12de 100644
--- a/applets/systemtray/qml/ExpandedRepresentation.qml
+++ b/applets/systemtray/qml/ExpandedRepresentation.qml
@@ -279,6 +279,40 @@ Item {

             KeyNavigation.up: pinButton

+            transform: Translate {
+                id: hiddenItemsViewTranslate
+            }
+
+            // Slide back in like a StackView pop when going back from an applet
+            ParallelAnimation {
+                id: backAnimation
+                NumberAnimation {
+                    target: hiddenItemsViewTranslate
+                    property: "x"
+                    from: (hiddenItemsView.mirrored ? 0.5 : -0.5) * hiddenItemsView.width
+                    to: 0
+                    duration: Kirigami.Units.longDuration
+                    easing.type: Easing.OutCubic
+                }
+                NumberAnimation {
+                    target: hiddenItemsView
+                    property: "opacity"
+                    from: 0
+                    to: 1
+                    duration: Kirigami.Units.longDuration
+                    easing.type: Easing.OutCubic
+                }
+            }
+
+            Connections {
+                target: systemTrayState
+                function onActiveAppletChanged() {
+                    if (!systemTrayState.activeApplet && systemTrayState.expanded) {
+                        backAnimation.restart();
+                    }
+                }
+            }
+
             onVisibleChanged: {
                 if (visible) {
                     layout.forceActiveFocus();
-- 
